public class DocumentService {

    public static Document generateDocument(Reservation reservation, RoomType roomType) {
        return switch (true) {
            case reservation.guestCpf != null -> generateComprovante(reservation, roomType);
            case reservation.companyCnpj != null -> generateFatura(reservation, roomType);
            case reservation.guestPassport != null -> generateBookingReceipt(reservation, roomType);
            default -> throw new IllegalArgumentException("Invalid reservation identification");
        };
    }

    private static Document generateComprovante(Reservation reservation, RoomType roomType) {
        String text = formatComprovante(
            reservation.id,
            reservation.guestName,
            reservation.guestCpf,
            reservation.roomNumber,
            roomType.type,
            reservation.checkIn,
            reservation.checkOut,
            reservation.nights,
            reservation.subtotal,
            reservation.discount,
            reservation.total
        );

        return new Document(
            "Comprovante de reserva",
            reservation.id,
            reservation.guestName,
            reservation.guestCpf,
            null,
            null,
            null,
            null,
            reservation.roomNumber,
            roomType.type,
            formatDateBR(reservation.checkIn),
