        sb.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
        if (discount > 0) {
            sb.append("Desconto: ").append(formatMoney(discount)).append("\n");
        }
        sb.append("Total: ").append(formatMoney(total));
        return sb.toString();
    }

