                "INSERT INTO messages (channel, to_address, subject, body) VALUES (?, ?, ?, ?)");
            stmt.setString(1, channel);
            stmt.setString(2, to);
            stmt.setString(3, subject);
            stmt.setString(4, body);
            stmt.executeUpdate();
        }
    }
}

