            while (rs.next()) {
                messages.add(new Message(
                    rs.getInt("id"),
                    rs.getString("channel"),
                    rs.getString("to_address"),
                    rs.getString("subject"),
                    rs.getString("body")
                ));
            }
        }

        return messages;
    }
}

